113	func TestTheStepGuardAcceptsTheConventionsOwnWording(t *testing.T) {
114		for _, steps := range [][]string{
115			{"Run helm template charts/api and fix the first error it reports.", "If a dependency is missing, run helm dependency build charts/api."},
116			{"Reference a directory that has its own kustomization.yaml, or", "move the file below dev."},
117			{"If this reference points outside the directory DevDesk mounts, scan the enclosing directory."},
118		} {
119			if problems := stepProblems(steps); len(problems) > 0 {
120				t.Errorf("%q flagged: %v", steps, problems)
121			}
122		}
123	}
