180	func TestTheStepsDevDeskWritesFollowTheConvention(t *testing.T) {
181		for name, lists := range stepSamples() {
182			for _, steps := range lists {
183				if len(steps) == 0 {
184					t.Errorf("%s returned no step for a sample", name)
185				}
186				for _, p := range stepProblems(steps) {
187					t.Errorf("%s: %s", name, p)
188				}
189			}
190		}
191		// The one list a function does not build: the constant the kustomize branch appends.
192		for _, p := range stepProblems([]string{kustomizeMountStep}) {
193			t.Errorf("kustomizeMountStep: %s", p)
194		}
195	}
