15	// Where the text of a finding comes from. The convention (docs/architecture/
16	// scanning.md, "Writing a Resolution, Steps and Repro for a new finding") has two
17	// provenance rules, and this guard reads the non-test sources of this package to
18	// hold them:
19	//
20	//	P1  a Repro of a Finding is only ever a value that localRepro (or a wrapper of
21	//	    it, found by the guard: a function whose every return is a call to a
22	//	    producer) returned, so the PlainWords refusal, the "no line from a
23	//	    container" rule and the "never copy the user's arguments" rule always
24	//	    apply. The empty string is allowed.
25	//	P2  a Steps of a Finding is only ever a value a *Steps function returned (the
26	//	    functions of steps.go), so the content guard of steps_guard_test.go sees
27	//	    every step a finding can carry. nil is allowed.
28	//
29	// A site is `Repro: x` in a composite literal, `y.Repro = x`, or the tuple form
30	// `y.Repro, y.RanFrom = a, b`. x is accepted when it is a call to a producer, a
31	// name that a producer's call defined in the same function and that nothing else
32	// assigns, or a parameter of the function that every caller in the package feeds
33	// with an accepted value (followed recursively).
34	//
35	// Limits, stated: it works on names, not types, so another struct with a field
36	// called Repro or Steps is held to the same rule; a producer reached through an
37	// alias, a function value or a method value is not seen; an assignment through a
38	// pointer to the string (`p := &f.Repro; *p = ...`), reflection, a Finding built
39	// by another package or a positional literal other than the ones it flags are out
40	// of its sight; flow is ignored inside a function (a name assigned once by a
41	// producer and once by anything else is refused, whatever the order); functions
42	// are keyed by name, so two methods of the same name in this package share one
43	// entry.
44	
45	// fieldRule is one of the two rules: the field it guards, what counts as a
46	// producer and what literal is a harmless zero value.
47	type fieldRule struct {
48		field    string
49		producer func(name string, wrappers map[string]bool) bool
50		zero     func(ast.Expr) bool
51	}
52	
53	var reproRule = fieldRule{
54		field:    "Repro",
55		producer: func(name string, wrappers map[string]bool) bool { return name == "localRepro" || wrappers[name] },
56		zero: func(e ast.Expr) bool {
57			lit, ok := e.(*ast.BasicLit)
58			return ok && lit.Kind == token.STRING && lit.Value == `""`
59		},
60	}
61	
62	var stepsRule = fieldRule{
63		field:    "Steps",
64		producer: func(name string, _ map[string]bool) bool { return strings.HasSuffix(name, "Steps") },
65		zero: func(e ast.Expr) bool {
66			id, ok := e.(*ast.Ident)
67			return ok && id.Name == "nil"
68		},
69	}
70	
71	type guardSource struct {
72		name string
73		file *ast.File
74		fset *token.FileSet
75	}
76	
77	type guardFunc struct {
78		decl   *ast.FuncDecl
79		source guardSource
80		params map[string]int
81	}
82	
83	func parseGuardSources(t *testing.T, sources map[string]string) []guardSource {
84		t.Helper()
85		fset := token.NewFileSet()
86		names := make([]string, 0, len(sources))
87		for name := range sources {
88			names = append(names, name)
89		}
90		slices.Sort(names)
91		out := make([]guardSource, 0, len(names))
92		for _, name := range names {
93			f, err := parser.ParseFile(fset, name, sources[name], 0)
94			if err != nil {
95				t.Fatalf("parse %s: %v", name, err)
96			}
97			out = append(out, guardSource{name, f, fset})
98		}
99		return out
100	}
101	
102	func packageGuardSources(t *testing.T) map[string]string {
103		t.Helper()
104		entries, err := os.ReadDir(".")
105		if err != nil {
106			t.Fatal(err)
107		}
108		sources := map[string]string{}
109		for _, e := range entries {
110			name := e.Name()
111			if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
112				continue
113			}
114			b, err := os.ReadFile(name)
115			if err != nil {
116				t.Fatal(err)
117			}
118			sources[name] = string(b)
119		}
120		if len(sources) == 0 {
121			t.Fatal("no source file read: the guard would pass on nothing")
122		}
123		return sources
124	}
125	
126	func exprString(e ast.Expr) string {
127		switch x := e.(type) {
128		case *ast.Ident:
129			return x.Name
130		case *ast.SelectorExpr:
131			return exprString(x.X) + "." + x.Sel.Name
132		case *ast.ParenExpr:
133			return exprString(x.X)
134		case *ast.StarExpr:
135			return "*" + exprString(x.X)
136		}
137		return ""
138	}
139	
140	// calleeName is the name of the function a call names directly, or "".
141	func calleeName(call *ast.CallExpr) string {
142		switch f := call.Fun.(type) {
143		case *ast.Ident:
144			return f.Name
145		case *ast.SelectorExpr:
146			return f.Sel.Name
147		}
148		return ""
149	}
150	
151	func flattenParams(decl *ast.FuncDecl) map[string]int {
152		params := map[string]int{}
153		i := 0
154		for _, field := range decl.Type.Params.List {
155			if len(field.Names) == 0 {
156				i++
157				continue
158			}
159			for _, n := range field.Names {
160				params[n.Name] = i
161				i++
162			}
163		}
164		return params
165	}
166	
167	// findWrappers returns the functions whose every return is a single call to a
168	// producer (or to a wrapper already found): renderRepro around localRepro.
169	func findWrappers(funcs map[string]guardFunc, rule fieldRule) map[string]bool {
170		wrappers := map[string]bool{}
171		for changed := true; changed; {
172			changed = false
173			for name, fn := range funcs {
174				if wrappers[name] || fn.decl.Body == nil || rule.producer(name, nil) {
175					continue
176				}
177				returns, all := 0, true
178				ast.Inspect(fn.decl.Body, func(n ast.Node) bool {
179					if _, lit := n.(*ast.FuncLit); lit {
180						return false
181					}
182					ret, ok := n.(*ast.ReturnStmt)
183					if !ok {
184						return true
185					}
186					returns++
187					call, isCall := (*ast.CallExpr)(nil), false
188					if len(ret.Results) == 1 {
189						call, isCall = ret.Results[0].(*ast.CallExpr)
190					}
191					if !isCall || !rule.producer(calleeName(call), wrappers) {
192						all = false
193					}
194					return true
195				})
196				if returns > 0 && all {
197					wrappers[name] = true
198					changed = true
199				}
200			}
201		}
202		return wrappers
203	}
204	
205	type scopeFacts struct {
206		produced map[string]bool // names a producer call defined
207		dirty    map[string]bool // names something else assigned
208	}
209	
210	// factsOf reads what a function assigns to which name.
211	func factsOf(body ast.Node, rule fieldRule, wrappers map[string]bool) scopeFacts {
212		facts := scopeFacts{map[string]bool{}, map[string]bool{}}
213		note := func(lhs []ast.Expr, rhs []ast.Expr) {
214			if len(rhs) == 1 {
215				if call, ok := rhs[0].(*ast.CallExpr); ok {
216					for i, l := range lhs {
217						name := exprString(l)
218						if i == 0 && rule.producer(calleeName(call), wrappers) {
219							facts.produced[name] = true
220						} else {
221							facts.dirty[name] = true
222						}
223					}
224					return
225				}
226			}
227			for i, l := range lhs {
228				name := exprString(l)
229				if name == "_" || name == "" {
230					continue
231				}
232				if len(lhs) == len(rhs) {
233					if call, ok := rhs[i].(*ast.CallExpr); ok && rule.producer(calleeName(call), wrappers) {
234						facts.produced[name] = true
235						continue
236					}
237				}
238				facts.dirty[name] = true
239			}
240		}
241		ast.Inspect(body, func(n ast.Node) bool {
242			switch s := n.(type) {
243			case *ast.AssignStmt:
244				note(s.Lhs, s.Rhs)
245			case *ast.ValueSpec:
246				names := make([]ast.Expr, len(s.Names))
247				for i, id := range s.Names {
248					names[i] = id
249				}
250				note(names, s.Values)
251			case *ast.RangeStmt:
252				for _, e := range []ast.Expr{s.Key, s.Value} {
253					if e != nil {
254						facts.dirty[exprString(e)] = true
255					}
256				}
257			}
258			return true
259		})
260		return facts
261	}
262	
263	// fieldViolations reports every site that sets rule.field from something the rule
264	// does not accept, as "file:line: function: reason", sorted. found is how many
265	// sites it examined, so a caller can tell a pass from a blind pass.
266	func fieldViolations(sources []guardSource, rule fieldRule) (violations []string, found int) {
267		funcs := map[string]guardFunc{}
268		for _, src := range sources {
269			for _, d := range src.file.Decls {
270				if fd, ok := d.(*ast.FuncDecl); ok {
271					funcs[fd.Name.Name] = guardFunc{fd, src, flattenParams(fd)}
272				}
273			}
274		}
275		wrappers := findWrappers(funcs, rule)
276		factsCache := map[string]scopeFacts{}
277		facts := func(fn guardFunc) scopeFacts {
278			key := fn.decl.Name.Name
279			if f, ok := factsCache[key]; ok {
280				return f
281			}
282			f := factsOf(fn.decl.Body, rule, wrappers)
283			factsCache[key] = f
284			return f
285		}
286	
287		var check func(fn guardFunc, e ast.Expr, seen map[string]bool) string
288		check = func(fn guardFunc, e ast.Expr, seen map[string]bool) string {
289			if rule.zero(e) {
290				return ""
291			}
292			if call, ok := e.(*ast.CallExpr); ok {
293				if rule.producer(calleeName(call), wrappers) {
294					return ""
295				}
296				return "value comes from a call to " + calleeName(call) + ", not from a producer"
297			}
298			name := exprString(e)
299			if name == "" {
300				return "value is an expression the guard does not follow; use a variable a producer returned"
301			}
302			f := facts(fn)
303			if f.dirty[name] {
304				return name + " is assigned from something other than a producer"
305			}
306			if f.produced[name] {
307				return ""
308			}
309			idx, isParam := fn.params[name]
310			if !isParam {
311				return name + " is not defined by a producer call in the function"
312			}
313			key := fn.decl.Name.Name + "#" + name
314			if seen[key] {
315				return ""
316			}
317			seen[key] = true
318			callers := 0
319			for _, caller := range funcs {
320				if caller.decl.Body == nil {
321					continue
322				}
323				var bad string
324				ast.Inspect(caller.decl.Body, func(n ast.Node) bool {
325					call, ok := n.(*ast.CallExpr)
326					if !ok || calleeName(call) != fn.decl.Name.Name {
327						return true
328					}
329					callers++
330					if idx >= len(call.Args) {
331						bad = "a call to " + fn.decl.Name.Name + " does not pass " + name
332					} else if why := check(caller, call.Args[idx], seen); why != "" && bad == "" {
333						bad = "via " + caller.decl.Name.Name + " at " + pos(caller.source, call) + ": " + why
334					}
335					return true
336				})
337				if bad != "" {
338					return name + " is a parameter and " + bad
339				}
340			}
341			if callers == 0 {
342				return name + " is a parameter nobody in the package passes a value to"
343			}
344			return ""
345		}
346	
347		report := func(fn *guardFunc, src guardSource, at ast.Node, why string) {
348			fname := "(package level)"
349			if fn != nil {
350				fname = fn.decl.Name.Name
351			}
352			violations = append(violations, pos(src, at)+": "+fname+": "+rule.field+": "+why)
353		}
354		visit := func(fn *guardFunc, src guardSource, root ast.Node) {
355			ast.Inspect(root, func(n ast.Node) bool {
356				var why string
357				switch s := n.(type) {
358				case *ast.CompositeLit:
359					if id, ok := s.Type.(*ast.Ident); ok && id.Name == "Finding" && len(s.Elts) > 0 {
360						if _, keyed := s.Elts[0].(*ast.KeyValueExpr); !keyed {
361							report(fn, src, s, "positional Finding literal: use keyed fields so the guard can read them")
362						}
363					}
364				case *ast.KeyValueExpr:
365					if id, ok := s.Key.(*ast.Ident); ok && id.Name == rule.field {
366						found++
367						if fn == nil {
368							if !rule.zero(s.Value) {
369								why = "set at package level"
370							}
371						} else {
372							why = check(*fn, s.Value, map[string]bool{})
373						}
374						if why != "" {
375							report(fn, src, s, why)
376						}
377					}
378				case *ast.AssignStmt:
379					for i, l := range s.Lhs {
380						sel, ok := l.(*ast.SelectorExpr)
381						if !ok || sel.Sel.Name != rule.field {
382							continue
383						}
384						found++
385						switch {
386						case fn == nil:
387							why = "set at package level"
388						case s.Tok != token.ASSIGN && s.Tok != token.DEFINE:
389							why = "modified in place with " + s.Tok.String()
390						case len(s.Rhs) == len(s.Lhs):
391							why = check(*fn, s.Rhs[i], map[string]bool{})
392						case len(s.Rhs) == 1:
393							call, isCall := s.Rhs[0].(*ast.CallExpr)
394							if !isCall || i != 0 || !rule.producer(calleeName(call), wrappers) {
395								why = "tuple assignment that is not a producer's first result"
396							}
397						}
398						if why != "" {
399							report(fn, src, s, why)
400						}
401					}
402				}
403				return true
404			})
405		}
406		for _, src := range sources {
407			for _, d := range src.file.Decls {
408				if fd, ok := d.(*ast.FuncDecl); ok {
409					if fd.Body != nil {
410						fn := funcs[fd.Name.Name]
411						visit(&fn, src, fd.Body)
412					}
413					continue
414				}
415				visit(nil, src, d)
416			}
417		}
418		sort.Strings(violations)
419		return violations, found
420	}
421	
422	func pos(src guardSource, n ast.Node) string {
423		p := src.fset.Position(n.Pos())
424		return src.name + ":" + strconv.Itoa(p.Line)
425	}
