487	func TestTheReproGuardCatchesAHandWrittenRepro(t *testing.T) {
488		got, found := fieldViolations(parseGuardSources(t, map[string]string{"bad.go": reproViolatingSource}), reproRule)
489		for _, fn := range []string{"literal", "concatenated", "assigned", "appended", "viaCall", "reassigned", "tupleFromElsewhere", "build", "positional"} {
490			if !violationIn(got, ": "+fn+": ") {
491				t.Errorf("the guard did not flag %s; violations:\n%s", fn, strings.Join(got, "\n"))
492			}
493		}
494		if found < 8 {
495			t.Errorf("examined %d sites, want at least 8", found)
496		}
497	}
